class Array:
    def __init__(self, capacity):
        self.data = [None] * capacity
        self.size = 0

    def resize(self, new_capacity):
        new_data = [None] * new_capacity
        for i in range(self.size):
            new_data[i] = self.data[i]
        self.data = new_data

    def add(self, index, e):
        if index < 0 or index > self.size:
            raise ValueError("Add failed. Require 0 <= index <= size.")

        if self.size == len(self.data):
            self.resize(2 * len(self.data))

        for i in range(self.size - 1, index - 1, -1):
            self.data[i + 1] = self.data[i]

        self.data[index] = e
        self.size += 1

def get(self, index):
    if index < 0 or index >= self.size:
        raise ValueError("Get failed. Index is illegal.")
    return self.data[index]

def contains(self, e):
    for i in range(self.size):
        if self.data[i] == e:
            return True
    return False

def find(self, e):
    for i in range(self.size):
        if self.data[i] == e:
            return i
    return -1

def __str__(self):
    res = []
    res.append(f"Queue: size = {self.size} , capacity = {self.get_capacity()}\n")
    res.append("front [")
    i = self.front
    while i != self.tail:
        res.append(str(self.data[i]))
        i = (i + 1) % len(self.data)
        if i != self.tail:
            res.append(", ")
    res.append("] tail")
    return "".join(res)

