class MiddleSearch:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

    def insert(self, node, value):
        if value < node.data:
            if node.left is None:
                node.left = MiddleSearch(value)
            else:
                self.insert(node.left, value)
        else:
            if node.right is None:
                node.right = MiddleSearch(value)
            else:
                self.insert(node.right, value)

