def has_value():
    params = request.json
    if not params:
        return jsonify({"error": "参数为空"}), 400

    for key, value in params.items():
        if key and key.strip():
            if base_service.has_value(key, value):
                return jsonify({"ok": f"{key}字段值重复", "code": 1})

    return jsonify({"ok": "无重复值", "code": 0})

